import { MakeLogicType, actions, afterMount, connect, kea, key, listeners, path, props } from 'kea'

import { experimentLogic } from 'scenes/experiments/experimentLogic'
import { type RecalculationPayload, experimentMetricsLogic } from 'scenes/experiments/experimentMetricsLogic'

import type { Experiment, ExperimentIdType } from '~/types'

export interface ExperimentExposuresWindowLogicProps {
    experiment: Experiment
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface experimentExposuresWindowLogicValues {
    exposuresAsOf: string | null // experimentLogic
    resultsQueryTo: string | null // experimentMetricsLogic
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface experimentExposuresWindowLogicActions {
    loadExposures: (refresh?: boolean | undefined) => boolean // experimentLogic
    setCurrentRecalculation: (recalculation: RecalculationPayload | null) => {
        recalculation: RecalculationPayload | null
    } // experimentMetricsLogic
    syncExposuresWindow: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface experimentExposuresWindowLogicMeta {
    key: ExperimentIdType
}

export type experimentExposuresWindowLogicType = MakeLogicType<
    experimentExposuresWindowLogicValues,
    experimentExposuresWindowLogicActions,
    ExperimentExposuresWindowLogicProps,
    experimentExposuresWindowLogicMeta
>

/**
 * Reloads the exposures when the window of the metric results moves, so both end at the same instant.
 * Separate from experimentLogic because that logic is keyed by id and cannot connect to the metrics logic,
 * which needs the experiment in its props.
 */
export const experimentExposuresWindowLogic = kea<experimentExposuresWindowLogicType>([
    props({} as ExperimentExposuresWindowLogicProps),
    key((props) => props.experiment.id),
    path((key) => ['products', 'experiments', 'exposures', 'experimentExposuresWindowLogic', String(key)]),
    connect((props: ExperimentExposuresWindowLogicProps) => ({
        values: [
            experimentLogic({ experimentId: props.experiment.id }),
            ['exposuresAsOf'],
            experimentMetricsLogic({ experiment: props.experiment }),
            ['resultsQueryTo'],
        ],
        actions: [
            experimentLogic({ experimentId: props.experiment.id }),
            ['loadExposures'],
            experimentMetricsLogic({ experiment: props.experiment }),
            ['setCurrentRecalculation'],
        ],
    })),
    actions({
        syncExposuresWindow: true,
    }),
    listeners(({ actions, values, selectors }) => ({
        /** Every poll dispatches this action, so react only when the window moves, not on every poll. */
        setCurrentRecalculation: (_, __, ___, previousState) => {
            if (selectors.resultsQueryTo(previousState) !== values.resultsQueryTo) {
                actions.syncExposuresWindow()
            }
        },
        syncExposuresWindow: () => {
            if (values.resultsQueryTo && values.resultsQueryTo !== values.exposuresAsOf) {
                actions.loadExposures()
            }
        },
    })),
    afterMount(({ actions }) => {
        actions.syncExposuresWindow()
    }),
])
